import { getFeatureFlagService } from '../services/FeatureFlagService';
import { FLAG_DEFINITIONS, type FlagKey, type FeatureFlags } from './flags';

type FeatureFlagEvaluationOptions = {
  userKey?: string;
};

export async function getFeatureFlags(
  options: FeatureFlagEvaluationOptions = {},
): Promise<FeatureFlags> {
  const service = getFeatureFlagService();
  const keys = Object.keys(FLAG_DEFINITIONS) as FlagKey[];

  const allFlags = await service.getAllFlags(options.userKey);
  const entries = await Promise.all(
    keys.map(async (key) => {
      const snakeKey = key
        .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
        .replace(/-/g, '_')
        .toUpperCase();
      const envKey = `RIVET_FLAG_${snakeKey}`;
      const envVal = process.env[envKey];
      if (envVal !== undefined) {
        return [key, { isEnabled: envVal !== 'false' }] as const;
      }

      if (key in allFlags) {
        return [key, { isEnabled: !!allFlags[key] }] as const;
      }

      const evaluated = await service.isFeatureEnabled(key, options.userKey);
      if (evaluated !== null) {
        return [key, { isEnabled: evaluated }] as const;
      }

      return [key, { isEnabled: FLAG_DEFINITIONS[key].default }] as const;
    }),
  );

  return Object.fromEntries(entries) as FeatureFlags;
}
